const d = $input.first().json;
const inputCtx = JSON.stringify({ sub_questions: d.results.map(r => r.sub_question) });
const outputData = JSON.stringify({ results: d.results });
const sql = `INSERT INTO agent_outputs (job_id, agent_name, input_context, output_data, model_used, latency_ms) VALUES (${esc(d.job_id)}, 'researcher', ${esc(inputCtx)}::jsonb, ${esc(outputData)}::jsonb, 'gemini-3.6-flash', ${d.latency_ms});`;

