return [{ json: { job_id: job.id, user_query: job.user_query, researched, _start: Date.now() } }];

parameters.jsonBody:
={{ JSON.stringify({
  contents: [{
    parts: [{
      text: `You are the Fact Checker agent. Given the research results below (sub-questions with sources and summaries), extract 6-10 distinct, concrete factual claims made across the research. For each claim, assess its status using EXACTLY one of these four values:
- "verified": supported by 2+ independent credible sources in the research
- "disputed": sources in the research conflict on this claim
- "unverifiable": cannot be confirmed from the given sources (vague, speculative, or unsupported by any listed source)
- "unverified": supported by only one source, not yet cross-checked
Return ONLY valid JSON, no markdown fences, in this exact shape:
{"claims": [{"claim_text": "...", "status": "verified", "evidence": ["source title 1", "source title 2"]}]}

Original question: ${$json.user_query}
Research data: ${JSON.stringify($json.researched)}`
    }]
  }],
  generationConfig: { temperature: 0.2, response_mime_type: "application/json" }
}) }}

