  if (typeof v === 'boolean') return String(v);
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return "'" + s.replace(/'/g, "''") + "'";
}

const d = $input.first().json;
const outputData = JSON.stringify({ claims: d.claims });
const sql = `INSERT INTO agent_outputs (job_id, agent_name, output_data, model_used, latency_ms) VALUES (${esc(d.job_id)}, 'fact_checker', ${esc(outputData)}::jsonb, 'gemini-3.6-flash', ${d.latency_ms});`;

return [{ json: { sql } }];

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return String(v);
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return "'" + s.replace(/'/g, "''") + "'";
}

const allowedStatus = ['unverified', 'verified', 'disputed', 'unverifiable'];
const d = $input.first().json;
const jobId = d.job_id;
const claims = d.claims || [];

if (claims.length === 0) {
  return [{ json: { sql: 'SELECT 1;' } }];
}

const rows = claims.map(c => {
  const status = allowedStatus.includes(c.status) ? c.status : 'unverified';
  return `(${esc(jobId)}, 'fact_checker', ${esc(c.claim_text)}, ${esc(status)}, ${esc(JSON.stringify(c.evidence || []))}::jsonb, now(), 'fact_checker')`;
}).join(',\n');

const sql = `INSERT INTO claims (job_id, agent_name, claim_text, status, evidence, checked_at, checked_by) VALUES ${rows};`;

return [{ json: { sql } }];

